from datetime import date, timedelta


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    if not isinstance(days, int) or isinstance(days, bool):
        raise TypeError

    holidays_set = set(holidays)

    if days == 0:
        current = start
        while current.weekday() >= 5 or current in holidays_set:
            current += timedelta(days=1)
        return current

    elif days > 0:
        current = start
        count = 0
        while count < days:
            current += timedelta(days=1)
            if current.weekday() < 5 and current not in holidays_set:
                count += 1
        return current

    else:
        current = start
        count = 0
        while count < -days:
            current -= timedelta(days=1)
            if current.weekday() < 5 and current not in holidays_set:
                count += 1
        return current


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    if first > last:
        return -count_workdays(last, first, holidays)

    holidays_set = set(holidays)
    count = 0
    current = first
    while current <= last:
        if current.weekday() < 5 and current not in holidays_set:
            count += 1
        current += timedelta(days=1)

    return count
